H.background();
const V = P.V, R = Math.max(0.1, P.R);
const I = V / R;
const Pw = V * I;
// auto-scale so the operating point (I, Pw) and the P = I^2 R curve stay
// on-screen at every slider setting (I up to 12 A, P up to 144 W).
const xMaxV = Math.max(I * 1.15, 1);
const yMaxV = Math.max(Pw * 1.15, 1);
const v = H.plot2d({ xMin: 0, xMax: xMaxV, yMin: 0, yMax: yMaxV, pad: 52 });
v.grid(); v.axes();
v.fn(x => x * x * R, { color: H.colors.accent, width: 3 });
const pulse = 6 + 2 * Math.sin(t * 3);
v.dot(I, Pw, { r: pulse, fill: H.colors.warn });
v.line(I, 0, I, Pw, { color: H.colors.good, width: 1.5, dash: [4, 4] });
v.line(0, Pw, I, Pw, { color: H.colors.violet, width: 1.5, dash: [4, 4] });
v.text("operating point", I, Pw, { color: H.colors.warn, size: 11 });
H.text("x: current I (A)   y: power P (W)", 60, H.H - 28, { color: H.colors.sub, size: 11 });
const gx = H.W - 150, gy = 90;
const glow = H.clamp(Pw / 144, 0, 1);
H.circle(gx, gy, 18 + 10 * glow * (0.6 + 0.4 * Math.sin(t * 4)), { fill: H.hsl(20, 90, 30 + 30 * glow) });
H.rect(gx - 26, gy - 9, 52, 18, { stroke: H.colors.sub, width: 2, radius: 3 });
H.text("R", gx, gy + 5, { color: H.colors.ink, size: 14, align: "center" });
const ax = gx - 70 + 8 * Math.sin(t * 2);
H.arrow(ax, gy, ax + 30, gy, { color: H.colors.accent, width: 3 });
H.text("I", ax + 14, gy - 10, { color: H.colors.accent, size: 13, align: "center" });
H.text("Electrical power: P = V·I = I²·R", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("V = " + V.toFixed(1) + " V   R = " + R.toFixed(1) + " Ω   I = " + I.toFixed(2) + " A   P = " + Pw.toFixed(2) + " W", 24, 54, { color: H.colors.sub, size: 13 });
H.legend([{ label: "P = I²R", color: H.colors.accent }, { label: "operating point", color: H.colors.warn }], 24, 78);
